import java.util.ArrayList;

class ArticulationPoints {

    private static final int NO_PARENT = -1;

    private static class DfsState {
        final boolean[] visited;
        final boolean[] isAP;
        final int[] disc;
        final int[] low;
        int timer;

        DfsState(int V) {
            visited = new boolean[V];
            isAP = new boolean[V];
            disc = new int[V];
            low = new int[V];
        }
    }

    private static ArrayList<ArrayList<Integer>> constructAdj(int V, int[][] edges) {
        ArrayList<ArrayList<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < V; i++) adj.add(new ArrayList<>());
        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }
        return adj;
    }

    private static void dfs(ArrayList<ArrayList<Integer>> adj, int u, int parent, DfsState state) {
        state.visited[u] = true;
        state.disc[u] = state.low[u] = ++state.timer;
        int children = 0;

        for (int v : adj.get(u)) {
            if (!state.visited[v]) {
                children++;
                dfs(adj, v, u, state);
                state.low[u] = Math.min(state.low[u], state.low[v]);
                if (parent != NO_PARENT && state.low[v] >= state.disc[u]) {
                    state.isAP[u] = true;
                }
            } else if (v != parent) {
                state.low[u] = Math.min(state.low[u], state.disc[v]);
            }
        }

        if (parent == NO_PARENT && children > 1) {
            state.isAP[u] = true;
        }
    }

    /**
     * Returns all articulation points in the graph, or [-1] if none exist.
     *
     * @param V   number of vertices
     * @param adj undirected adjacency list
     */
    static ArrayList<Integer> articulationPoints(int V, ArrayList<ArrayList<Integer>> adj) {
        if (adj == null || V <= 0) return new ArrayList<>();

        DfsState state = new DfsState(V);
        for (int u = 0; u < V; u++) {
            if (!state.visited[u]) {
                dfs(adj, u, NO_PARENT, state);
            }
        }

        ArrayList<Integer> result = new ArrayList<>();
        for (int u = 0; u < V; u++) {
            if (state.isAP[u]) result.add(u);
        }

        if (result.isEmpty()) result.add(-1);
        return result;
    }

    public static void main(String[] args) {
        int V = 5;
        int[][] edges = {{0, 1}, {1, 4}, {2, 3}, {2, 4}, {3, 4}};

        ArrayList<ArrayList<Integer>> adj = constructAdj(V, edges);
        ArrayList<Integer> ans = articulationPoints(V, adj);

        for (int u : ans) System.out.print(u + " ");
        System.out.println();
    }
}

