import java.util.ArrayList;

class ArticulationPoints {

    private static final int NO_PARENT = -1;

    /** Builds an undirected adjacency list from an edge array. */
    static ArrayList<ArrayList<Integer>> constructAdj(int V, int[][] edges) {
        ArrayList<ArrayList<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < V; i++) adj.add(new ArrayList<>());

        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }
        return adj;
    }

    /**
     * DFS helper that computes discovery and low-link values and marks
     * articulation points via Tarjan's algorithm.
     */
    static void findPoints(ArrayList<ArrayList<Integer>> adj, int u,
                           boolean[] visited, int[] disc, int[] low,
                           int[] timer, int parent, boolean[] isAP) {
        visited[u] = true;
        disc[u] = low[u] = ++timer[0];
        int children = 0;

        for (int v : adj.get(u)) {
            if (!visited[v]) {
                children++;
                findPoints(adj, v, visited, disc, low, timer, u, isAP);
                low[u] = Math.min(low[u], low[v]);

                if (parent != NO_PARENT && low[v] >= disc[u]) {
                    isAP[u] = true;
                }
            } else if (v != parent) {
                low[u] = Math.min(low[u], disc[v]);
            }
        }

        if (parent == NO_PARENT && children > 1) {
            isAP[u] = true;
        }
    }

    /**
     * Returns all articulation points in the graph, or [-1] if none exist.
     *
     * @param V   number of vertices
     * @param adj undirected adjacency list
     */
    static ArrayList<Integer> articulationPoints(int V, ArrayList<ArrayList<Integer>> adj) {
        boolean[] visited = new boolean[V];
        boolean[] isAP = new boolean[V];
        int[] disc = new int[V];
        int[] low = new int[V];
        int[] timer = {0};

        for (int u = 0; u < V; u++) {
            if (!visited[u]) {
                findPoints(adj, u, visited, disc, low, timer, NO_PARENT, isAP);
            }
        }

        ArrayList<Integer> result = new ArrayList<>();
        for (int u = 0; u < V; u++) {
            if (isAP[u]) result.add(u);
        }

        if (result.isEmpty()) result.add(-1);
        return result;
    }

    public static void main(String[] args) {
        int V = 5;
        int[][] edges = {{0, 1}, {1, 4}, {2, 3}, {2, 4}, {3, 4}};

        ArrayList<ArrayList<Integer>> adj = constructAdj(V, edges);
        ArrayList<Integer> ans = articulationPoints(V, adj);

        for (int u : ans) System.out.print(u + " ");
        System.out.println();
    }
}
